// Copies data/city.json into src/city-data.js (and the example city into src/example-city.js) so
// index.html works when you simply double-click it (browsers block fetch() on file:// pages).
// Run after editing data/city.json or data/examples/*.json:  node scripts/build-data.js
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
function wrap(file, variable, out, label) {
  const json = JSON.parse(fs.readFileSync(path.join(root, file), 'utf8'));
  fs.writeFileSync(path.join(root, 'src', out),
    '// GENERATED by scripts/build-data.js from ' + file + '. Do not edit by hand.\n' +
    'window.' + variable + ' = ' + JSON.stringify(json, null, 2) + ';\n');
  console.log('wrote src/' + out + ' (' + label + ')');
}
wrap('data/city.json', 'CITY_DATA', 'city-data.js', 'the built-in city');
wrap('data/examples/port-marlow.json', 'CITY_EXAMPLE', 'example-city.js', 'the example city');
